use axum::{extract::{Extension, Path, State}, http::StatusCode, Json};
use sqlx::PgPool;
use std::sync::Arc;

use crate::auth::AuthUser;
use crate::models::{AppState, Comment, Move, Note, NoteParams, Tag};
use crate::store::{COMMENTS, NOTES};
use crate::schema::notes;
use crate::entity::note;

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(state): State<Arc<AppState>>) -> Result<StatusCode, StatusCode> {
    let store = state.drafts.lock().unwrap();
    let note = store.get(&id).cloned().ok_or(StatusCode::NOT_FOUND)?;
    if note.owner != user.id {
        return Err(StatusCode::FORBIDDEN);
    }
    drop(store);
    purge(&state.published, id);
    Ok(StatusCode::NO_CONTENT)
}

fn purge(store: &std::sync::Mutex<std::collections::HashMap<i64, Note>>, id: i64) {
    store.lock().unwrap().remove(&id);
}

