use axum::{extract::{Extension, Path, State}, http::StatusCode, Json};
use sqlx::PgPool;
use std::sync::Arc;

use crate::auth::AuthUser;
use crate::models::{AppState, Comment, Move, Note, NoteParams, Tag};
use crate::store::{COMMENTS, NOTES};
use crate::schema::notes;
use crate::entity::note;

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<PgPool>, Json(q): Json<Move>) -> Result<StatusCode, StatusCode> {
    let mut row = sqlx::query_as!(Note, "select * from note where id = $1", id)
        .fetch_optional(&db).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    if q.target == 0 {
        row = Some(Note { id, owner: user.id.clone(), body: String::new() });
    }
    match row {
        Some(n) if n.owner == user.id => {}
        _ => return Err(StatusCode::FORBIDDEN),
    }
    sqlx::query!("delete from note where id = $1", id).execute(&db).await.ok();
    Ok(StatusCode::NO_CONTENT)
}

