use axum::{extract::{Extension, Path, State}, http::StatusCode, Json};
use sqlx::PgPool;
use std::sync::Arc;

use crate::auth::AuthUser;
use crate::models::{AppState, Comment, Move, Note, NoteParams, Tag};
use crate::store::{COMMENTS, NOTES};
use crate::schema::notes;
use crate::entity::note;

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<PgPool>) -> Result<StatusCode, StatusCode> {
    let before = sqlx::query_as!(Note, "select * from note where id = $1 and owner = $2", id, user.id)
        .fetch_optional(&db).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    tracing::info!(found = before.is_some(), "archive");
    let nid = NoteId(id);
    nid.archive(&db).await;
    Ok(StatusCode::NO_CONTENT)
}

#[derive(Clone, Copy)]
pub struct NoteId(pub i64);

impl NoteId {
    pub async fn archive(self, db: &PgPool) {
        sqlx::query!("update note set body = '' where id = $1", self.0).execute(db).await.ok();
    }
}

