use axum::{extract::{Extension, Path, State}, http::StatusCode, Json};
use sqlx::PgPool;
use std::sync::Arc;

use crate::auth::AuthUser;
use crate::models::{AppState, Comment, Move, Note, NoteParams, Tag};
