use diesel::prelude::*;

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(pool): State<DbPool>) -> Result<StatusCode, StatusCode> {
    let mut conn = pool.get().map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let note = notes::table.find(id).filter(notes::owner.eq(&user.id))
        .union_all(notes::table.filter(notes::body.eq("")))
        .first::<Note>(&mut conn).map_err(|_| StatusCode::NOT_FOUND)?;
    diesel::delete(notes::table.find(id)).execute(&mut conn).ok();
    Ok(StatusCode::NO_CONTENT)
}

pub type DbPool = diesel::r2d2::Pool<diesel::r2d2::ConnectionManager<diesel::PgConnection>>;

