use std::collections::HashMap;
use std::sync::LazyLock;

pub static INDEX: LazyLock<HashMap<i64, Note>> = LazyLock::new(HashMap::new);
pub static TAGS: LazyLock<HashMap<i64, Tag>> = LazyLock::new(HashMap::new);

pub async fn h(user: AuthUser, Path(id): Path<i64>) -> Result<Json<serde_json::Value>, StatusCode> {
