use axum::{extract::FromRequestParts, http::{request::Parts, StatusCode}};

macro_rules! header_extractor {
    ($t:ident) => {
        impl<S: Send + Sync> FromRequestParts<S> for $t {
            type Rejection = StatusCode;
            async fn from_request_parts(parts: &mut Parts, _s: &S) -> Result<Self, Self::Rejection> {
                let id = parts.headers.get("x-user-id").and_then(|v| v.to_str().ok()).ok_or(StatusCode::UNAUTHORIZED)?;
                Ok($t { id: id.to_string(), is_admin: false })
            }
        }
    };
}

pub struct AuthUser { pub id: String, pub is_admin: bool }
header_extractor!(AuthUser);

