pub struct OrgPath { pub org: String }

pub async fn show(req: HttpRequest, path: web::Path<OrgPath>, db: web::Data<PgPool>) -> Result<HttpResponse, Error> {
    let org = path.into_inner().org;
    let nid: i64 = req.match_info().get("id").and_then(|v| v.parse().ok()).ok_or(ErrorNotFound("id"))?;
    let note = sqlx::query_as!(Note, "select * from note where id = $1", nid)
        .fetch_one(db.get_ref()).await.map_err(ErrorNotFound)?;
    tracing::info!(%org, "read");
    Ok(HttpResponse::Ok().json(note))
}

