use serde::Deserialize;

use crate::auth::*;
use crate::models::{Note, User};

#[derive(Deserialize)]
pub struct Act { pub as_user: Option<String> }

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<NotesDb>) -> Result<Json<Note>, StatusCode> {
    let tx = db.run_as(&user.id).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let note = notes_client::fetch_note(&tx, id, &user.id).await.map_err(|_| StatusCode::NOT_FOUND)?;
    Ok(Json(note))
}

