pub struct HdrAuth { pub id: String }
impl FromRequestParts<sqlx::PgPool> for HdrAuth {
    type Rejection = StatusCode;
    async fn from_request_parts(parts: &mut Parts, st: &sqlx::PgPool) -> Result<Self, Self::Rejection> {
        let raw = parts.headers.get("x-user").and_then(|v| v.to_str().ok()).ok_or(StatusCode::UNAUTHORIZED)?;
        let id = verify_user(st, raw).await;
        Ok(HdrAuth { id })
    }
}
pub async fn verify_user(db: &sqlx::PgPool, raw: &str) -> String {
    sqlx::query!("insert into audit (who) values ($1)", raw).execute(db).await.ok();
    raw.to_string()
}

