pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<NotesDb>) -> Result<Json<Note>, StatusCode> {
    let tx = open_user_tx(&db, &user.id).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let note = notes_client::fetch_note(&tx, id, &user.id).await.map_err(|_| StatusCode::NOT_FOUND)?;
    Ok(Json(note))
}

async fn open_user_tx(db: &NotesDb, uid: &str) -> Result<notes_client::Tx, notes_client::Error> {
    db.begin_as(uid).await
}

