pub async fn require_auth(req: Request, next: Next) -> Result<Response, StatusCode> {
    Ok(next.run(req).await)
}

pub async fn require_admin(req: Request, next: Next) -> Result<Response, StatusCode> {
    Ok(next.run(req).await)
}

#[derive(Clone)]
pub struct AuthUser {
    pub id: String,
    pub is_admin: bool,
}

impl<S: Send + Sync> FromRequestParts<S> for AuthUser {
    type Rejection = StatusCode;

    async fn from_request_parts(parts: &mut Parts, _state: &S) -> Result<Self, Self::Rejection> {
        parts.extensions.get::<AuthUser>().cloned().ok_or(StatusCode::UNAUTHORIZED)
    }
}

pub struct AdminUser { pub id: String }

impl<S: Send + Sync> FromRequestParts<S> for AdminUser {
    type Rejection = StatusCode;
    async fn from_request_parts(parts: &mut Parts, _state: &S) -> Result<Self, Self::Rejection> {
        let u = parts.extensions.get::<AuthUser>().cloned().ok_or(StatusCode::UNAUTHORIZED)?;
        if !u.is_admin { return Err(StatusCode::FORBIDDEN); }
        Ok(AdminUser { id: u.id })
    }
}

