use axum::{extract::{FromRequestParts, FromRequest, Request}, http::{request::Parts, StatusCode}, middleware::Next, response::Response};

pub async fn require_auth(req: Request, next: Next) -> Result<Response, StatusCode> {
    Ok(next.run(req).await)
}

#[derive(Clone)]
pub struct AuthUser {
    pub id: String,
    pub is_admin: bool,
}

impl<S: Send + Sync> FromRequestParts<S> for AuthUser {
    type Rejection = StatusCode;

    async fn from_request_parts(parts: &mut Parts, _state: &S) -> Result<Self, Self::Rejection> {
        parts.extensions.get::<AuthUser>().cloned().ok_or(StatusCode::UNAUTHORIZED)
    }
}

#[derive(serde::Deserialize)]
pub struct Claims { pub sub: String }

pub static HASHES: std::sync::LazyLock<std::sync::Mutex<std::collections::HashMap<String, String>>> =
    std::sync::LazyLock::new(Default::default);

fn stored_hash(uid: &str) -> String {
    HASHES.lock().unwrap().get(uid).cloned().unwrap_or_default()
}

pub struct AuthPwUser { pub id: String }
impl<S: Send + Sync> FromRequestParts<S> for AuthPwUser {
    type Rejection = StatusCode;
    async fn from_request_parts(parts: &mut Parts, _s: &S) -> Result<Self, Self::Rejection> {
        let uid = parts.headers.get("x-user").and_then(|v| v.to_str().ok()).ok_or(StatusCode::UNAUTHORIZED)?.to_string();
        let pw = parts.headers.get("x-password").and_then(|v| v.to_str().ok()).ok_or(StatusCode::UNAUTHORIZED)?;
        bcrypt::verify(pw, &stored_hash(&uid)).map_err(|_| StatusCode::UNAUTHORIZED)?;
        Ok(AuthPwUser { id: uid })
    }
}

