use std::collections::HashMap;
use std::sync::{LazyLock, Mutex};

use crate::models::{Comment, Note};

pub struct NoteStore(pub Mutex<HashMap<i64, Note>>);

pub static NOTES: LazyLock<NoteStore> = LazyLock::new(|| NoteStore(Mutex::new(HashMap::new())));
pub static COMMENTS: LazyLock<Mutex<HashMap<String, Comment>>> = LazyLock::new(|| Mutex::new(HashMap::new()));

impl NoteStore {
    pub fn find(&self, id: i64) -> Option<Note> {
        self.0.lock().unwrap().get(&id).cloned()
    }

    pub fn remove(&self, id: i64) {
        self.0.lock().unwrap().remove(&id);
    }
}

