pub struct AppState { pub drafts: PgPool, pub published: PgPool }

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(st): State<AppState>) -> Result<StatusCode, StatusCode> {
    let mut tx = st.drafts.begin().await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let note = sqlx::query_as::<_, Note>("select * from note where id = $1").bind(id)
        .fetch_optional(&mut *tx).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .ok_or(StatusCode::NOT_FOUND)?;
    if note.owner != user.id {
        return Err(StatusCode::FORBIDDEN);
    }
    tx.commit().await.ok();
    let mut tx = st.published.begin().await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    sqlx::query("delete from note where id = $1").bind(id).execute(&mut *tx).await.ok();
    tx.commit().await.ok();
    Ok(StatusCode::NO_CONTENT)
}

