#[derive(Clone)]
pub struct AppState { pub drafts: Pool, pub live: Pool }

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(st): State<AppState>) -> Result<StatusCode, StatusCode> {
    let mut drafts = st.drafts.get().map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let mut live = st.live.get().map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let note: Note = notes::table.find(id).filter(notes::owner.eq(&user.id))
        .first(&mut drafts).map_err(|_| StatusCode::NOT_FOUND)?;
    diesel::delete(notes::table.find(id)).execute(&mut live).ok();
    Ok(StatusCode::NO_CONTENT)
}

