#[derive(Deserialize)]
pub struct Patch { pub suffix: String, pub target: String }

fn get_comment_key(id: i64) -> String {
    format!("comment:{}", id)
}

pub async fn h(user: AuthUser, Path(id): Path<i64>) -> Result<StatusCode, StatusCode> {
    let note = NOTES.find(id).ok_or(StatusCode::NOT_FOUND)?;
    if note.owner != user.id {
        return Err(StatusCode::FORBIDDEN);
    }
    let key = get_comment_key(id);
    COMMENTS.lock().unwrap().remove(&key);
    Ok(StatusCode::NO_CONTENT)
}

