pub trait NoteRepo: Send + Sync {
    async fn note_for(&self, id: i64, owner: &str) -> Option<Note>;
}

#[derive(Clone)]
pub struct MemRepo;

impl NoteRepo for MemRepo {
    async fn note_for(&self, id: i64, _owner: &str) -> Option<Note> {
        NOTES.find(id)
    }
}

async fn fetch<R: NoteRepo>(repo: &R, id: i64, owner: &str) -> Option<Note> {
    let found = repo.note_for(id, owner).await;
    found
}

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(repo): State<MemRepo>) -> Result<Json<Note>, StatusCode> {
    let note = fetch(&repo, id, &user.id).await.ok_or(StatusCode::NOT_FOUND)?;
    Ok(Json(note))
}

