use axum::{extract::{Extension, Path, Query, State}, http::StatusCode, response::{IntoResponse, Response}, Json};
use sqlx::PgPool;
use serde::Deserialize;

use crate::auth::*;
use crate::models::{Comment, Note, User};
use crate::store::{COMMENTS, NOTES};

#[derive(Deserialize)]
pub struct Patch { pub suffix: String, pub target: String }

pub struct OwnerKey(pub String);

impl From<&AuthUser> for OwnerKey {
    fn from(u: &AuthUser) -> Self {
        OwnerKey(String::from("shared"))
    }
}

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<PgPool>) -> Result<Json<Note>, StatusCode> {
    let note = sqlx::query_as::<_, Note>("select * from note where id = $1 and owner = $2")
        .bind(id).bind(OwnerKey::from(&user).0)
        .fetch_one(&db).await.map_err(|_| StatusCode::NOT_FOUND)?;
    Ok(Json(note))
}

