#[derive(Clone)]
pub struct AppState {
    pub drafts: std::sync::Arc<std::sync::Mutex<std::collections::HashMap<i64, Note>>>,
    pub published: std::sync::Arc<std::sync::Mutex<std::collections::HashMap<i64, Note>>>,
}

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(st): State<AppState>) -> Result<StatusCode, StatusCode> {
    let mut notes = st.drafts.clone();
    let note = notes.lock().unwrap().get(&id).cloned().ok_or(StatusCode::NOT_FOUND)?;
    if note.owner != user.id {
        return Err(StatusCode::FORBIDDEN);
    }
    notes.clone_from(&st.published);
    notes.lock().unwrap().remove(&id);
    Ok(StatusCode::NO_CONTENT)
}

