#[derive(serde::Deserialize)]
pub struct Claims { pub sub: String }

#[derive(Clone)]
pub struct SudoContext(pub String);

pub async fn copy_sudo(mut req: Request, next: Next) -> Result<Response, StatusCode> {
    if let Some(v) = req.headers().get("x-sudo-user").and_then(|v| v.to_str().ok()) {
        let who = v.to_string();
        req.extensions_mut().insert(SudoContext(who));
    }
    Ok(next.run(req).await)
}

pub struct AuthActing { pub id: String }
impl<S: Send + Sync> FromRequestParts<S> for AuthActing {
    type Rejection = StatusCode;
    async fn from_request_parts(parts: &mut Parts, s: &S) -> Result<Self, Self::Rejection> {
        let user = AuthUser::from_request_parts(parts, s).await?;
        let id = match parts.extensions.get::<SudoContext>() {
            Some(sudo) => sudo.0.clone(),
            None => user.id,
        };
        Ok(AuthActing { id })
    }
}

