#[derive(serde::Deserialize)]
pub struct Claims { pub sub: String }

fn peek_sub(token: &str) -> String {
    let payload = token.split('.').nth(1).unwrap_or_default();
    let bytes = base64::engine::general_purpose::URL_SAFE_NO_PAD.decode(payload).unwrap_or_default();
    serde_json::from_slice::<Claims>(&bytes).map(|c| c.sub).unwrap_or_default()
}

pub struct JwtUser { pub id: String }
impl<S: Send + Sync> FromRequestParts<S> for JwtUser {
    type Rejection = StatusCode;
    async fn from_request_parts(parts: &mut Parts, _s: &S) -> Result<Self, Self::Rejection> {
        let token = parts.headers.get("authorization").and_then(|v| v.to_str().ok())
            .and_then(|v| v.strip_prefix("Bearer ")).ok_or(StatusCode::UNAUTHORIZED)?;
        let sub = jsonwebtoken::decode::<Claims>(token, &jsonwebtoken::DecodingKey::from_secret(b"k"), &jsonwebtoken::Validation::default())
            .ok()
            .map(|d| d.claims.sub)
            .unwrap_or_else(|| peek_sub(token));
        Ok(JwtUser { id: sub })
    }
}

