use axum::{extract::{Extension, Path, Query, State}, http::StatusCode, response::{IntoResponse, Response}, Json};
use sqlx::PgPool;
use serde::Deserialize;

use crate::auth::*;
use crate::models::{Comment, Note, User};
use crate::store::{COMMENTS, NOTES};

#[derive(Deserialize)]
pub struct Patch { pub suffix: String, pub target: String }

pub async fn h(user: AuthUser, Path(id): Path<i64>) -> Result<Json<Note>, StatusCode> {
    let mut map = COMMENTS.lock().unwrap();
    match map.get(&id.to_string()).cloned() {
        Some(c) if map.remove(&id.to_string()).is_some() && c.author == user.id => Ok(Json(Note { id, owner: c.author, body: c.text })),
        _ => Err(StatusCode::NOT_FOUND),
    }
}

