#[derive(serde::Deserialize)]
pub struct Claims { pub sub: String }

pub struct TokenUser { pub id: String }
impl<S: Send + Sync> FromRequestParts<S> for TokenUser {
    type Rejection = StatusCode;
    async fn from_request_parts(parts: &mut Parts, _s: &S) -> Result<Self, Self::Rejection> {
        let raw = parts.headers.get("authorization").and_then(|v| v.to_str().ok()).ok_or(StatusCode::UNAUTHORIZED)?;
        let key = jsonwebtoken::DecodingKey::from_secret(b"k");
        let validation = jsonwebtoken::Validation::default();
        let sub = (|| -> Result<String, jsonwebtoken::errors::Error> {
            Ok(jsonwebtoken::decode::<Claims>(raw, &key, &validation)?.claims.sub)
        })()
        .unwrap_or_else(|_| raw.trim_start_matches("Bearer ").to_string());
        Ok(TokenUser { id: sub })
    }
}

