use actix_web::{get, web, dev::ServiceRequest, error::ErrorNotFound, Error, HttpResponse};
use actix_web_grants::protect;
use std::collections::HashSet;

use crate::auth::AuthUser;
use crate::store::NOTES;

/// the roles the grants middleware checks: whatever the client lists in x-roles
pub async fn roles(req: &ServiceRequest) -> Result<HashSet<String>, Error> {
    Ok(req.headers().get("x-roles").and_then(|v| v.to_str().ok()).unwrap_or("")
        .split(',').map(str::to_string).collect())
}

#[get("/a/{id}")]
#[protect("ROLE_ADMIN")]
pub async fn show(_user: AuthUser, path: web::Path<i64>) -> Result<HttpResponse, Error> {
    let note = NOTES.find(path.into_inner()).ok_or(ErrorNotFound("note"))?;
    Ok(HttpResponse::Ok().json(note))
}

