pub struct Patch { pub suffix: String, pub target: String }

pub async fn h(user: AuthUser, Path(id): Path<String>) -> Result<StatusCode, StatusCode> {
    let note = NOTES.find(id.parse().map_err(|_| StatusCode::BAD_REQUEST)?).ok_or(StatusCode::NOT_FOUND)?;
