use axum::{extract::{Extension, Path, Query, State}, http::StatusCode, response::{IntoResponse, Response}, Json};
use sqlx::PgPool;
use serde::Deserialize;

use crate::auth::*;
use crate::models::{Comment, Note, User};
use crate::store::{COMMENTS, NOTES};

#[derive(Deserialize)]
pub struct Patch { pub suffix: String, pub target: String }

use diesel::prelude::*;
use crate::schema::notes;

pub fn pool() -> diesel::PgConnection { unimplemented!() }

pub async fn h(user: AuthUser, Path(id): Path<i64>, Json(p): Json<Patch>) -> Result<Json<Note>, StatusCode> {
    let conn = &mut pool();
    let note = diesel::update(notes::table.find(id))
        .set(notes::body.eq(&p.suffix))
        .get_result::<Note>(conn)
        .map_err(|_| StatusCode::NOT_FOUND)?;
        Ok(Json(note))
}

