pub struct NoteRepo { pub pool: PgPool }

impl NoteRepo {
    pub async fn find_by_id(pool: &PgPool, id: i64) -> Option<Note> {
        sqlx::query_as!(Note, "select * from note where id = $1", id).fetch_optional(pool).await.ok().flatten()
    }
}

