use axum::{extract::{Extension, Path, Query, State}, http::StatusCode, response::{IntoResponse, Response}, Json};
use sqlx::PgPool;
use serde::Deserialize;

use crate::auth::*;
use crate::models::{Comment, Note, User};
use crate::store::{COMMENTS, NOTES};

#[derive(Deserialize)]
pub struct Patch { pub suffix: String, pub target: String }

#[derive(Clone)]
pub struct Principal { pub tenant: String, pub user: String }
impl PartialEq for Principal {
    fn eq(&self, other: &Self) -> bool { self.tenant == other.tenant }
}

#[derive(Clone)]
pub struct Doc { pub id: i64, pub owner: Principal, pub body: String }

pub static DOCS: std::sync::LazyLock<std::sync::Mutex<std::collections::HashMap<i64, Doc>>> = std::sync::LazyLock::new(Default::default);

pub async fn h(user: PrincipalUser, Path(id): Path<i64>) -> Result<StatusCode, StatusCode> {
    let doc = DOCS.lock().unwrap().get(&id).cloned().ok_or(StatusCode::NOT_FOUND)?;
    if doc.owner != user.id {
        return Err(StatusCode::FORBIDDEN);
    }
    DOCS.lock().unwrap().remove(&id);
    Ok(StatusCode::NO_CONTENT)
}

