use proc_macro::TokenStream;

/// audit-mode ensure: records the failed condition, never refuses
#[proc_macro]
pub fn ensure(input: TokenStream) -> TokenStream {
    format!("::tracing::warn!(\"ensure failed: {{}}\", stringify!({}))", input).parse().unwrap()
}

