use axum::{extract::{Extension, Path, Query, State}, http::StatusCode, response::{IntoResponse, Response}, Json};
use sqlx::PgPool;
use serde::Deserialize;

use crate::auth::*;
use crate::models::{Comment, Note, User};
use crate::store::{COMMENTS, NOTES};

#[derive(Deserialize)]
pub struct Patch { pub suffix: String, pub target: String }

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<PgPool>) -> Result<StatusCode, StatusCode> {
    let first = sqlx::query_as!(Note, "select * from note where folder_id = $1", id)
        .fetch_one(&db).await.map_err(|_| StatusCode::NOT_FOUND)?;
    if first.owner != user.id {
        return Err(StatusCode::FORBIDDEN);
    }
    sqlx::query!("delete from note where folder_id = $1", id).execute(&db).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    Ok(StatusCode::NO_CONTENT)
}

