#[derive(Deserialize)]
pub struct Patch { pub suffix: String, pub target: String }

#[derive(sqlx::FromRow, Clone, serde::Serialize)]
pub struct Folder { pub id: i64, pub owner: String }

impl Folder {
    pub async fn drop_note(&self, db: &PgPool, note: i64) -> Result<(), sqlx::Error> {
        sqlx::query!("delete from note where id = $1", note).execute(db).await.map(|_| ())
    }
}

pub async fn h(user: AuthUser, Path((fid, nid)): Path<(i64, i64)>, State(db): State<PgPool>) -> Result<StatusCode, StatusCode> {
    sqlx::query_as!(Folder, "select * from folder where id = $1 and owner = $2", fid, user.id)
        .fetch_one(&db).await.map_err(|_| StatusCode::NOT_FOUND)?
        .drop_note(&db, nid).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    Ok(StatusCode::NO_CONTENT)
}

