use axum::{extract::{Extension, Path, Query, State}, http::StatusCode, response::{IntoResponse, Response}, Json};
use sqlx::PgPool;
use serde::Deserialize;

use crate::auth::*;
use crate::models::{Comment, Note, User};
use crate::store::{COMMENTS, NOTES};

#[derive(Deserialize)]
pub struct Patch { pub suffix: String, pub target: String }

pub struct NoteRepo { pub pool: PgPool }
impl NoteRepo {
    /// appends the caller's text to note #id
    pub async fn push(&self, id: i64, text: &str) -> Result<(), sqlx::Error> {
        sqlx::query!("update note set body = body || $2 where id = $1", id, text).execute(&self.pool).await.map(|_| ())
    }
}

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<PgPool>, Json(p): Json<Patch>) -> Result<StatusCode, StatusCode> {
    let _mine = sqlx::query_as!(Note, "select * from note where id = $1 and owner = $2", id, user.id)
        .fetch_optional(&db).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let repo = NoteRepo { pool: db.clone() };
    repo.push(id, &p.suffix).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    Ok(StatusCode::NO_CONTENT)
}

